import admin from "firebase-admin";
import crypto from "crypto";
import { getFirestore } from "firebase-admin/firestore";
import firebaseConfig from "../../firebase-applet-config.json";

const getFirebaseAdminDb = () => {
    return getFirestore(admin.app(), (firebaseConfig as any).firestoreDatabaseId || '(default)');
};

export const verifyPaystackSignature = (req: any, secret: string) => {
  const hash = crypto.createHmac('sha512', secret).update(JSON.stringify(req.body)).digest('hex');
  return hash === req.headers['x-paystack-signature'];
};

export const verifyPaystackTransaction = async (reference: string, secretKey: string) => {
  const url = `https://api.paystack.co/transaction/verify/${encodeURIComponent(reference)}`;
  const res = await fetch(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${secretKey}`
    }
  });
  
  if (!res.ok) {
    throw new Error(`Paystack verification failed: ${res.statusText}`);
  }
  
  const data = await res.json();
  if (!data.status) {
    throw new Error(`Paystack verification API error: ${data.message}`);
  }
  
  return data.data; // { status, reference, amount, metadata, customer, etc. }
};

export const activateSubscription = async (uid: string, type: string, planName: string, amount: number, reference: string, transactionId: string) => {
  const fsDb = getFirebaseAdminDb();
  
  // Prevent duplicate activation
  const paymentQuery = await fsDb.collection('payments').where('paystackReference', '==', reference).limit(1).get();
  if (!paymentQuery.empty) {
    const existing = paymentQuery.docs[0].data();
    if (existing.status === 'successful') {
      return { success: true, message: 'Already activated' }; // Idempotent
    }
  }

  const userRef = fsDb.collection('users').doc(uid);
  const userDoc = await userRef.get();
  if (!userDoc.exists) {
    throw new Error("User not found in Firestore");
  }

  const now = new Date();
  const batch = fsDb.batch();

  // Create payment record
  const paymentRef = fsDb.collection('payments').doc();
  batch.set(paymentRef, {
    uid,
    email: userDoc.data()?.email || "",
    type: type || 'subscription',
    planName: type === 'intelligence' ? 'intelligence' : planName,
    amount,
    paystackReference: reference,
    paystackTransactionId: String(transactionId),
    status: 'successful',
    verifiedByBackend: true,
    createdAt: now.toISOString(),
    verifiedAt: now.toISOString()
  });

  if (type === 'intelligence') {
    const currentCredits = userDoc.data()?.intelligenceCredits || 0;
    const newCredits = currentCredits + 3;
    
    batch.update(userRef, {
      intelligenceCredits: newCredits,
      intelligenceActive: true,
      lastPaymentAmount: amount,
      lastPaymentDate: now.toISOString(),
      updatedAt: now.toISOString()
    });

    const lgRef = fsDb.collection('intelligence_transactions').doc();
    batch.set(lgRef, {
      uid,
      action: "purchase",
      creditsBefore: currentCredits,
      creditsAfter: newCredits,
      timestamp: now.toISOString()
    });
  } else {
    // Subscription Logic
    const expiryDate = new Date();
    expiryDate.setDate(now.getDate() + 30); // 30 days duration

    batch.update(userRef, {
      currentPlan: planName,
      subscriptionActive: true,
      subscriptionStartDate: now.toISOString(),
      subscriptionExpiryDate: expiryDate.toISOString(),
      paystackReference: reference,
      lastPaymentAmount: amount,
      lastPaymentDate: now.toISOString(),
      paymentStatus: 'successful',
      updatedAt: now.toISOString()
    });

    // Create subscription log
    const logRef = fsDb.collection('subscription_logs').doc();
    batch.set(logRef, {
      uid,
      action: "subscription_created",
      planName,
      timestamp: now.toISOString(),
      performedBy: "system"
    });
  }

  await batch.commit();
  
  return { success: true, message: type === 'intelligence' ? "Intelligence credits added" : "Subscription activated" };
};

export const consumeIntelligenceCredit = async (uid: string) => {
  const fsDb = getFirebaseAdminDb();
  const userRef = fsDb.collection('users').doc(uid);
  
  return await fsDb.runTransaction(async (transaction: any) => {
    const userDoc = await transaction.get(userRef);
    if (!userDoc.exists) throw new Error("User not found");
    
    const credits = userDoc.data().intelligenceCredits || 0;
    if (credits <= 0) {
      throw new Error("Insufficient intelligence credits");
    }
    
    transaction.update(userRef, {
      intelligenceCredits: credits - 1,
      intelligenceActive: (credits - 1) > 0,
      updatedAt: new Date().toISOString()
    });
    
    const lgRef = fsDb.collection('intelligence_transactions').doc();
    transaction.set(lgRef, {
      uid,
      action: "usage",
      creditsBefore: credits,
      creditsAfter: credits - 1,
      timestamp: new Date().toISOString()
    });
    
    return { success: true, remaining: credits - 1 };
  });
};

export const handlePaymentFailure = async (uid: string | null, email: string, reference: string, amount: number, planName: string) => {
    try {
        const fsDb = getFirebaseAdminDb();
        const paymentRef = fsDb.collection('payments').doc();
        await paymentRef.set({
            uid: uid || "unknown",
            email,
            planName,
            amount,
            paystackReference: reference,
            paystackTransactionId: "none",
            status: 'failed',
            verifiedByBackend: true,
            createdAt: new Date().toISOString(),
            verifiedAt: new Date().toISOString()
        });
        
        if (uid) {
            const logRef = fsDb.collection('subscription_logs').doc();
            await logRef.set({
                uid,
                action: "subscription_cancelled",
                planName,
                timestamp: new Date().toISOString(),
                performedBy: "system"
            });
        }
    } catch(e) {
        console.error("Failed to log payment failure", e);
    }
};

export const processExpiredSubscriptions = async () => {
    const fsDb = getFirebaseAdminDb();
    const now = new Date().toISOString();
    
    // Find expired
    const expiredQuery = await fsDb.collection('users')
      .where('subscriptionActive', '==', true)
      .where('subscriptionExpiryDate', '<', now)
      .get();
      
    if (expiredQuery.empty) return 0;

    let count = 0;
    const batches = [];
    let currentBatch = fsDb.batch();
    let optsInBatch = 0;

    for (const doc of expiredQuery.docs) {
        const uid = doc.id;
        const currentPlan = doc.data().currentPlan;
        
        currentBatch.update(doc.ref, {
            subscriptionActive: false,
            paymentStatus: 'expired',
            currentPlan: 'free',
            updatedAt: now
        });
        
        const logRef = fsDb.collection('subscription_logs').doc();
        currentBatch.set(logRef, {
            uid,
            action: 'subscription_expired',
            planName: currentPlan,
            timestamp: now,
            performedBy: 'system'
        });
        
        optsInBatch += 2;
        count++;

        if (optsInBatch >= 400) {
            batches.push(currentBatch.commit());
            currentBatch = fsDb.batch();
            optsInBatch = 0;
        }
    }
    
    if (optsInBatch > 0) {
        batches.push(currentBatch.commit());
    }
    
    await Promise.all(batches);
    return count;
};
