export interface OHLC {
  timestamp: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume?: number;
}

const marketDataCache: Record<string, OHLC[]> = {};
let lastUpdateTimestamps: Record<string, string> = {};

// We define our supported pairs natively, no more Binance proxies
export const SUPPORTED_PAIRS = [
  'EUR/USD', 'GBP/USD', 'USD/JPY', 'USD/CAD', 'AUD/USD', 'NZD/USD', 
  'USD/CHF', 'EUR/JPY', 'GBP/JPY', 'AUD/JPY', 'XAU/USD', 'XAG/USD'
];

export function updateMarketDataPrice(pair: string, price: number) {
  if (!marketDataCache[pair]) {
    marketDataCache[pair] = [];
  }

  const cache = marketDataCache[pair];
  const now = new Date();
  
  // Align timestamp to current 5-minute candle
  const coeff = 1000 * 60 * 5;
  const currentCandleTime = new Date(Math.floor(now.getTime() / coeff) * coeff).toISOString();
  
  if (cache.length === 0 || cache[cache.length - 1].timestamp !== currentCandleTime) {
    // Start a new candle
    cache.push({
      timestamp: currentCandleTime,
      open: price,
      high: price,
      low: price,
      close: price,
      volume: 0
    });
    if (cache.length > 500) {
      cache.shift(); // Keep max 500
    }
  } else {
    // Update existing candle
    const candle = cache[cache.length - 1];
    candle.high = Math.max(candle.high, price);
    candle.low = Math.min(candle.low, price);
    candle.close = price;
  }

  lastUpdateTimestamps[pair] = now.toISOString();
}

export function startMarketDataEngine() {
  console.log("Live Trading Market Data Engine initialized. Ready to receive prices...");
  // Now relies on prices being pushed mechanically
}

export function getCachedMarketData(pair: string): OHLC[] | null {
  return marketDataCache[pair] || null;
}

export function getSystemConfig() {
  return {
    supportedPairs: SUPPORTED_PAIRS,
    lastUpdates: lastUpdateTimestamps,
    cacheSize: Object.keys(marketDataCache).reduce((acc, pair) => {
      acc[pair] = marketDataCache[pair].length;
      return acc;
    }, {} as Record<string, number>)
  };
}

